parameters.jsCode:
const item = $input.first().json || {};
const wf = item.workflow || {};
const execution = item.execution || {};
const error = execution.error || item.error || {};

const wfName = wf.name || 'Workflow desconocido';
const wfId = wf.id || 'N/A';
const execId = execution.id || 'N/A';
const nodeName = error.node?.name || 'Nodo no especificado';
const errorMessage = error.message || 'Error no detallado';
const timestamp = new Date().toISOString();

const LF = String.fromCharCode(10);
const mensaje = [
  '🚨 ALERTA CRÍTICA: Fallo en Workflow n8n',
  '',
  `• Workflow: ${wfName} (${wfId})`,
  `• Nodo fallido: ${nodeName}`,
  `• ID Ejecución: ${execId}`,
  `• Hora (CR): ${timestamp}`,
  '',
  `• Detalle del error:`,
  `${errorMessage}`,
  '',
  '⚠️ Se requiere revisión técnica en la consola de n8n.'
].join(LF);

return [{ json: { mensaje, wfName, execId, nodeName, errorMessage } }];

